from solution import odd_bit_set_number


def test_issue_example_10_equals_15():
    """Example: odd_bit_set_number(10) == 15."""
    assert odd_bit_set_number(10) == 15  # 0b1010 | 0b0101 = 0b1111 = 8+4+2+1 = 15


def test_issue_zero_stays_zero():
    """Set all odd bits of a given number with n=0 stays 0."""
    assert odd_bit_set_number(0) == 0  # no bits, mask 0, 0 | 0 = 0


def test_issue_one_stays_one():
    """Set all odd bits of a given number with n=1 stays 1."""
    assert odd_bit_set_number(1) == 1  # 0b1 | 0b1 = 0b1 = 1


def test_issue_two_becomes_three():
    """Set all odd bits of a given number with n=2 gives 3."""
    assert odd_bit_set_number(2) == 3  # 0b10 | 0b01 = 0b11 = 2+1 = 3


def test_issue_four_becomes_five():
    """Set all odd bits of a given number with n=4 gives 5."""
    assert odd_bit_set_number(4) == 5  # 0b100 | 0b101 = 0b101 = 4+1 = 5


def test_issue_eight_becomes_thirteen():
    """Set all odd bits of a given number with n=8 gives 13."""
    assert odd_bit_set_number(8) == 13  # 0b1000 | 0b0101 = 0b1101 = 8+4+1 = 13


def test_issue_seven_stays_seven():
    """Set all odd bits of a given number with n=7 stays 7."""
    assert odd_bit_set_number(7) == 7  # 0b111 | 0b101 = 0b111 = 4+2+1 = 7


def test_issue_fortytwo_becomes_sixtythree():
    """Set all odd bits of a given number with n=42 gives 63."""
    assert odd_bit_set_number(42) == 63  # 0b101010 | 0b010101 = 0b111111 = 32+16+8+4+2+1 = 63


def test_issue_hundred_becomes_hundredseventeen():
    """Set all odd bits of a given number with n=100 gives 117."""
    assert odd_bit_set_number(100) == 117  # 0b1100100 | 0b1010101 = 0b1110101 = 64+32+16+4+1 = 117


def test_contract_returns_int():
    """Contract: odd_bit_set_number(n) returns an int."""
    assert isinstance(odd_bit_set_number(10), int)  # 10 -> 0b1111 = 8+4+2+1 = 15, type is int


def test_contract_idempotent_result():
    """Contract: setting odd bits twice gives same result."""
    assert odd_bit_set_number(odd_bit_set_number(8)) == 13  # 8 -> 13 = 8+4+1, 13 -> 13 = 8+4+1


def test_contract_preserves_original_one_bits():
    """Contract: setting odd bits never clears already set bits."""
    assert (odd_bit_set_number(8) & 8) == 8  # 13 & 8 = 8, bit 8 = 8 kept
